package com.example.activite.web.controller;
import com.example.activite.domain.Vehicule; import com.example.activite.service.IVehiculeService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.Parameter; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/vehicules") @RequiredArgsConstructor @Tag(name="Véhicules",description="Gestion des véhicules") public class VehiculeController { private final IVehiculeService vehiculeService;
@GetMapping @Operation(summary="Lister les véhicules") @ApiResponse(responseCode="200",description="Liste retournée") public List<Vehicule> findAll(){return vehiculeService.findAll();}
@GetMapping("/{id}") @Operation(summary="Consulter un véhicule") @ApiResponses({@ApiResponse(responseCode="200",description="Véhicule trouvé"),@ApiResponse(responseCode="404",description="Véhicule introuvable")}) public Vehicule findById(@Parameter(description="Identifiant du véhicule") @PathVariable Long id){return vehiculeService.findById(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Créer un véhicule") @ApiResponses({@ApiResponse(responseCode="201",description="Véhicule créé"),@ApiResponse(responseCode="400",description="Données invalides")}) public Vehicule create(@RequestBody Vehicule v){return vehiculeService.create(v);}
@PutMapping("/{id}") @Operation(summary="Modifier un véhicule") @ApiResponses({@ApiResponse(responseCode="200",description="Véhicule modifié"),@ApiResponse(responseCode="400",description="Données invalides"),@ApiResponse(responseCode="404",description="Véhicule introuvable")}) public Vehicule update(@PathVariable Long id,@RequestBody Vehicule v){return vehiculeService.update(id,v);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Supprimer un véhicule") @ApiResponses({@ApiResponse(responseCode="204",description="Véhicule supprimé"),@ApiResponse(responseCode="404",description="Véhicule introuvable")}) public void deleteById(@PathVariable Long id){vehiculeService.deleteById(id);}}
